/** Shows a chip for each claim being said now, with its verdict once there is one. */
function showDueChips(): void {
  const video = playerVideo();
  if (!enabled || status.state !== "ready" || !video || adShowing()) return;
  const now = video.currentTime;
  for (const claim of status.claims) {
    const due =
      claim.seconds <= now && now < claim.seconds + CHIP_WINDOW_SECONDS;
    if (!due || claim.chip === "final") continue;
    const settled =
      claim.check.state === "done" || claim.check.state === "failed";
    if (settled || claim.chip === "none") showChip(claim);
    claim.chip = settled ? "final" : "pending";
  }
}

function showChip(claim: LiveClaim): void {
  const host = overlayHost();
  if (!enabled || !host) return;
  let chips = document.getElementById(CHIPS_ID);
  if (!toggle) {
    toggle = element("button");
    toggle.id = TOGGLE_ID;
    toggle.type = "button";
    toggle.addEventListener("click", (event) => {
      event.stopPropagation(); // Not a click on the video.
      if (status.state === "error") return status.retry();
      if (status.state === "idle") return start();
      if (onShorts()) return toggleCard();
      listOpen = !listOpen;
      render();
      : status.state === "idle"
        ? "Fact-check this video"
        : "Claims in this video worth checking";
  toggle.setAttribute(
    "aria-expanded",
    String(shorts ? openClaim !== null : listOpen),
  );
}

/** On a Short, opens the claim said most recently, or closes the open one. */
function toggleCard(): void {
  if (status.state !== "ready") return;
  if (openClaim) return closeCard();
  const video = playerVideo();
  const now = video?.currentTime ?? 0;
  const said = status.claims.filter((claim) => claim.seconds <= now).at(-1);
  openClaim = said ?? status.claims[0] ?? null;
  if (openClaim) video?.pause();
  render();
}

function closeCard(): void {
  openClaim = null;
  render();
  playerVideo()
    ?.play()
    .catch(() => {}); // Staying paused is fine.
}

/**
 * On a Short, the open claim's verdict and sources on the paused video, one
