// Checks two arithmetic claims with the real prompt: one true, one false.
import { pathToFileURL } from "node:url";
import { resolve } from "node:path";

const { checkClaim, costOf, totals } = await import(
  pathToFileURL(resolve("server/checker.ts")).href
);
const claims = [
  "17 times 23 equals 391.",
  "25 percent of 80 is 25.",
];
for (const claim of claims) {
  const verdict = await checkClaim(
    { time: "0:05", quote: claim, claim },
    "Quick math tricks",
  );
  console.log(
    `${claim} -> ${verdict.verdict} (${verdict.method}, ${verdict.sources.length} sources): ${verdict.explanation}`,
  );
}
console.log(`searches: ${totals.searches}, cost: $${costOf(totals).toFixed(4)}`);

