def sub(p, pairs):
    s = open(p, encoding="utf-8").read()
    for a, b in pairs:
        assert a in s, (p, a[:70])
        s = s.replace(a, b, 1)
    open(p, "w", encoding="utf-8", newline="\n").write(s)


def cut(p, start, end, new):
    s = open(p, encoding="utf-8").read()
    a = s.index(start)
    b = s.index(end, a)
    open(p, "w", encoding="utf-8", newline="\n").write(s[:a] + new + s[b:])


