// Runs the server against a stand-in store that speaks just enough of the
// Redis protocol, and checks the day's spend is picked up at start.
import { spawn } from "node:child_process";
import { createServer } from "node:net";

const data = new Map();
const today = `spent:${new Date().toISOString().slice(0, 10)}`;
data.set(today, "0.200000");
const store = createServer((socket) => {
  socket.on("data", (chunk) => {
    const parts = String(chunk)
      .split("\r\n")
      .filter((_, i) => i > 0 && i % 2 === 0);
    if (parts[0] === "SET") {
      data.set(parts[1], parts[2]);
      socket.write("+OK\r\n");
    } else {
      const value = data.get(parts[1]);
      socket.write(
        value === undefined ? "$-1\r\n" : `$${value.length}\r\n${value}\r\n`,
      );
    }
  });
}).listen(6390, "127.0.0.1");

const server = spawn(process.execPath, ["server/main.ts"], {
  env: { ...process.env, REDIS_URL: "redis://127.0.0.1:6390", PORT: "10001" },
  stdio: "inherit",
});
await new Promise((resolve) => setTimeout(resolve, 2500));
const budget = await (await fetch("http://127.0.0.1:10001/budget")).json();
console.log("budget after start:", JSON.stringify(budget));
data.delete(today);
await fetch("http://127.0.0.1:10001/claims", {
  method: "POST",
  body: JSON.stringify({ videoId: "hmkoFDMAvkc", title: "t", transcript: " " }),
});
await new Promise((resolve) => setTimeout(resolve, 500));
console.log("saved after a request:", data.get(today));
server.kill();
store.close();
process.exit(0);

