function renderMarks(): void {
  const existing = document.getElementById(MARKS_ID);
  const video = playerVideo();
  const bar = document.querySelector(
    onShorts()
      ? "yt-progress-bar.ytPlayerProgressBarHost"
      : "#movie_player .ytp-progress-bar",
  );
